#!/usr/bin/env python3
"""Generate tb_isense_azloop.cir: AZ loop-gain deck with a deck-local copy of r1_isense_ch (r1_isense_ch_lg) taken from
schematic/r1_isense.spice, loop broken at the auxiliary-pair gates (1 GH DC path, 1 F AC injection)."""
import os
here = os.path.dirname(os.path.abspath(__file__))
net = open(os.path.join(here, "..", "schematic", "r1_isense.spice")).read()
a = net.index(".subckt r1_isense_ch "); b = net.index(".ends r1_isense_ch", a) + len(".ends r1_isense_ch")
sub = net[a:b]
sub = sub.replace(".subckt r1_isense_ch isp isn outp outn vref vcm ibias az_lv azh_lv vdda vdd vss",
                  ".subckt r1_isense_ch_lg isp isn outp outn vref vcm ibias az_lv azh_lv vdda vdd vss tpa tpb")
assert "XA1 f1 h1 atail" in sub and "XA2 f2 h2 atail" in sub
sub = sub.replace("XA1 f1 h1 atail", "XA1 f1 hg1 atail").replace("XA2 f2 h2 atail", "XA2 f2 hg2 atail")
sub = sub.replace(".ends r1_isense_ch", "* LOOP BREAK (test only): DC through 1 GH, AC injected through 1 F at the aux-pair gates\n"
                  "Lb1 h1 hg1 1e9\nLb2 h2 hg2 1e9\nCi1 hg1 tpa 1\nCi2 hg2 tpb 1\n"
                  "* replica of the aux gate load at the open end (h1/h2 already carry 1 pF hold caps)\n.ends r1_isense_ch_lg")
HEAD = '* r1_isense auto-zero loop gain (return ratio), loop broken at the auxiliary-pair gates during AZ hold (az = azh = 1).\n* Loop: x1a -> hold switch -> h1 (1 pF) -> aux pair XA1 -> fold node f1 -> cascode -> x1a (each side; the stage-2 Miller\n* loop and CMFB are inside). The break uses a 1 GH / 1 F pair (DC operating point unchanged); the gate load of the\n* aux devices (about 0.07 fF/um2 x 32 um2) is small against the 1 pF hold cap at the open end, so no replica is added.\n* Differential: AC +0.5/-0.5 at the two gates, T_dm = -(v(h1)-v(h2))/(v(hg1)-v(hg2)); common mode: +0.5/+0.5.\n* Uses a deck-local copy of r1_isense_ch (r1_isense_ch_lg, generated by gen_tb_isense_azloop.py from the netlist of record).\n.lib /foss/pdks/ihp-sg13g2/libs.tech/ngspice/models/cornerMOSlv.lib @@MOS@@\n.lib /foss/pdks/ihp-sg13g2/libs.tech/ngspice/models/cornerMOShv.lib @@MOS@@\n.lib /foss/pdks/ihp-sg13g2/libs.tech/ngspice/models/cornerRES.lib @@RES@@\n.lib /foss/pdks/ihp-sg13g2/libs.tech/ngspice/models/cornerCAP.lib @@CAP@@\n.temp @@TEMP@@\n.include /work/designs/r1-joint/blocks/r1_isense/schematic/r1_isense.spice\n'
TAIL = '\n.option gmin=1e-12\nVdda vdda 0 dc @@VDDA@@\nVdd vdd 0 dc @@VDD@@\n* IDEAL REFERENCE SOURCES (this step only)\nVref vref 0 dc 1.05\nVcm vcm 0 dc 0.6\nIbias vdda ibias dc {5u*(@@TEMP@@+273.15)/300.15}\nVaz az 0 dc @@VDD@@\nVazh azh 0 dc @@VDD@@\nVcmi isn 0 dc 0\nVin isp isn dc 0\nVta tpa 0 dc 0 ac 0.5\nVtb tpb 0 dc 0 ac -0.5\nXDUT isp isn outp outn vref vcm ibias az azh vdda vdd 0 tpa tpb r1_isense_ch_lg\nCLP outp 0 2p\nCLN outn 0 2p\n.control\nset wr_singlescale\nset wr_vecnames\nac dec 40 10 10g\nlet t = -(v(xdut.h1)-v(xdut.h2))/(v(xdut.hg1)-v(xdut.hg2))\nlet tdb = db(t)\nlet tph = cph(t)*180/pi\nwrdata @@OUT@@_dm.txt tdb tph\nalter vtb ac = 0.5\nac dec 40 10 10g\nlet t = -(v(xdut.h1)+v(xdut.h2))/(v(xdut.hg1)+v(xdut.hg2))\nlet tdb = db(t)\nlet tph = cph(t)*180/pi\nwrdata @@OUT@@_cm.txt tdb tph\n.endc\n.end\n'
open(os.path.join(here, "tb_isense_azloop.cir"), "w").write(HEAD + sub + TAIL)
print("ok")
